const assert = require('node:assert/strict');
const { fixture, delivery } = require('./scripts/lib/cloudflare-autopilot-test.cjs');
const { cloudflareScheduled, cloudflareQueue } = require('./src/lib/runtime/cloudflare/autopilot.ts');
const { jobId } = require('./src/lib/platform/cloudflareContracts.ts');
(async () => {
  await fixture(async context => {
    await context.store.createTask({ id: 'exact-replay-smoke', type: context.input.type, payload: context.input.payload, enabled: true, nextRunAt: context.now, intervalMs: 3600000 });
    const controller = { scheduledTime: context.now };
    await cloudflareScheduled(controller, context.env);
    await cloudflareScheduled(controller, context.env);
    assert.equal(context.sent.length, 1);
    assert.equal((await context.db.prepare('SELECT COUNT(*) AS n FROM automation_jobs').first()).n, 1);
    const capturedBody = context.sent[0];
    const serializedBody = JSON.stringify(capturedBody);
    assert.equal(capturedBody.jobId, jobId('cron:exact-replay-smoke:' + context.now));
    assert.equal((await context.store.get(capturedBody.jobId)).status, 'PENDING');
    const message = delivery(capturedBody, 'exact-original-message');
    const batch = { queue: 'sandeal-local-jobs', messages: [message] };
    await cloudflareQueue(batch, context.env);
    assert.equal(message.ackCount, 1);
    assert.deepEqual(message.retries, []);
    assert.equal((await context.history()).length, 1);
    const completed = await context.store.get(capturedBody.jobId);
    assert.equal(completed.status, 'SUCCEEDED');
    assert.equal(completed.attemptCount, 1);
    assert.deepEqual(completed.result, { snapshotCreated: true });
    await cloudflareQueue(batch, context.env);
    assert.equal(message.ackCount, 2);
    assert.deepEqual(message.retries, []);
    assert.equal(JSON.stringify(message.body), serializedBody);
    assert.equal(message.body, capturedBody);
    assert.equal((await context.history()).length, 1);
    assert.equal((await context.store.get(capturedBody.jobId)).attemptCount, 1);
    assert.equal((await context.store.get(capturedBody.jobId)).status, 'SUCCEEDED');
    console.log('PASS exact captured Cron-to-Queue message replay completes one D1 domain effect');
    console.log(JSON.stringify({ CRON: 'PASS', QUEUE: 'PASS', D1: 'PASS', JOB_STATE: 'SUCCEEDED', DUPLICATE_CRON: 'SAFE', DUPLICATE_DELIVERY: 'SAFE', DUPLICATE_DOMAIN_EFFECT: 0, EXACT_MESSAGE_REPLAY: true }));
  });
})().catch(error => { console.error('FAIL exact message replay', error); process.exitCode = 1; });
